local function ReadJournal()
    local quests = {}
    if not C_QuestLog or not C_QuestLog.GetNumQuestLogEntries or not C_QuestLog.GetInfo then return quests end
    for index = 1, C_QuestLog.GetNumQuestLogEntries() or 0 do
        local info = C_QuestLog.GetInfo(index)
        if info and not info.isHeader and type(info.questID) == "number" and info.questID > 0 then
            quests[info.questID] = true
        end
    end
    return quests
end--[[APR_DIAG]]; ReadJournal = APRTrace("APR-Core/features/questing/QuestLogSuggestions.lua:11:ReadJournal#1", ReadJournal)--[[/APR_DIAG]]

local function Eligible(key, data, maps)
    if type(data) ~= "table" or not data.label or data.temporary or type(data.steps) ~= "table" then return false end
    if not APR:IsRouteCompatibleWithClient(data) or APR:GetRouteVisibility(key, true) ~= "visible" then return false end
    if not APR:CanStartRoute(key) or not APR:EvaluateRouteConditions(data.conditions) then return false end
    local low, high = APR.RouteCatalog:GetLevelRange(key, data, maps)
    local level = APR:GetPlayerEffectiveLevel()
    return (not low or level >= low) and (not high or level <= high)
end--[[APR_DIAG]]; Eligible = APRTrace("APR-Core/features/questing/QuestLogSuggestions.lua:23:Eligible#2", Eligible)--[[/APR_DIAG]]

-- PickUp is evidence of a match, but an accepted quest resumes at its first
-- remaining objective/turn-in, never at its already-completed acceptance.
local function Match(steps, quests, checkpoint)
    local seen, count, first, pickup = {}, 0
    for index, step in ipairs(steps) do
        checkpoint()
        if (step.PickUp or step.Qpart or step.QpartDB or step.Done) and APR:AreConditionalFiltersMet(step) then
            for _, field in ipairs({ "PickUp", "Qpart", "QpartDB", "Done" }) do
                for key, value in pairs(type(step[field]) == "table" and step[field] or {}) do
                    checkpoint()
                    local id = tonumber(field == "Qpart" and key or value)
                    if id and quests[id] then
                        if not seen[id] then seen[id], count = true, count + 1 end
                        if field == "PickUp" then
                            pickup = pickup or index
                        elseif not first then
                            first = index
                        end
                    end
                end
            end
        end
    end
    return count, first or pickup
end--[[APR_DIAG]]; Match = APRTrace("APR-Core/features/questing/QuestLogSuggestions.lua:34:Match#3", Match)--[[/APR_DIAG]]

function Search:Cancel(expected)
    if expected and self.job ~= expected then return end
    local job = self.job
    self.job = nil
    if job and job.timer then job.timer:Cancel() end
end--[[APR_DIAG]]; Search.Cancel = APRTrace("APR-Core/features/questing/QuestLogSuggestions.lua:58:Search:Cancel#4", Search.Cancel)--[[/APR_DIAG]]

local function Current(job)
